/**
 * Entry point for the reusable "sync onboarding guide" workflow
 * (Requirement #48). Runs at every release tag, alongside consolidate/
 * draft-release-notes/analyze — not on every push, unlike draft-log-entry.
 * Always regenerates, no drift-check: a real release is itself a
 * meaningful "the world changed" event, the same reasoning
 * consolidate-release.ts already applies to master docs, so there's no
 * "is this actually necessary" question to answer first the way there is
 * for a script that would otherwise fire on every single push.
 *
 * Synthesizes from what Devlore has already generated about the project
 * (the current-state snapshot, recorded decisions, master docs) rather
 * than raw log-entry history — a "start here" doc for a new contributor,
 * distinct from the end-user-facing User Manual. Writes back into the
 * project repo itself (source of truth, discoverable directly on GitHub)
 * and mirrors a copy into the vault at projects/<name>/onboarding.md, the
 * same dual-storage pattern as docs/TEST_PLAN.md and docs/USER_MANUAL.md.
 */
export declare function syncOnboardingGuide(): Promise<void>;
